def solve(payload):
    s=dict(payload['initial']); applied=[]
    for e in payload.get('events',[]):
        if e['op']=='start': s['status']='doing'
        elif e['op']=='complete': s['status']='done'
        applied.append(e['id'])
    return {'state':s,'applied':applied,'rejected':[],'ignored':[]}

def solve(payload):
    s=dict(payload['initial']); applied=[]
    for e in payload.get('events',[]):
        if e['op']=='label': s['labels'].append(e['value'])
        elif e['op']=='unlabel' and e['value'] in s['labels']: s['labels'].remove(e['value'])
        applied.append(e['id'])
    return {'state':s,'applied':applied,'rejected':[],'ignored':[]}
